// Helper: Tra cứu theo ID
function getFoodById(id) {
  return FOOD_DATABASE.find(f => f.id === id) || null;
}

// Helper: Tính toán lại dinh dưỡng theo kích cỡ khẩu phần (S = 70%, M = 100%, L = 130%)
function calculatePortionNutrition(food, size = 'M') {
  let multiplier = 1.0;
  if (size === 'S') multiplier = 0.7;
  else if (size === 'L') multiplier = 1.3;
  
  return {
    size,
    multiplier,
    calories: Math.round(food.calories * multiplier),
    protein: +(food.protein * multiplier).toFixed(1),
    fat: +(food.fat * multiplier).toFixed(1),
    carb: +(food.carb * multiplier).toFixed(1),
    weightG: Math.round(food.weightG * multiplier)
  };
}

// Helper: Kiểm tra dị ứng đối chiếu với hồ sơ người dùng
function checkFoodAllergies(food, userAllergens = []) {
  if (!userAllergens || userAllergens.length === 0 || !food.allergens) return [];
  const matched = [];
  userAllergens.forEach(allergenKey => {
    if (food.allergens.includes(allergenKey)) {
      matched.push(ALLERGEN_DICT[allergenKey] ? ALLERGEN_DICT[allergenKey].label : allergenKey);
    }
  });
  return matched;
}
